mapper.select:
select id, bill_type, case bill_type when 1 then '房租' when 2 then '电费' when 3 then '水费' else '其他' end bill_type_name, amount, billing_period, due_date, status, paid_time, trade_no from tenant_bill where user_id = #{userId} and is_deleted = 0
and bill_type = #{billType}
order by status, billing_period desc, id desc
